//! `index` generated by `mlirformat tblgen` (`index.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "index.gen.rs"]
mod index;

#[test]
fn index_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<index::Index>();
    common::Fixtures::check_dialect(&opt, "index");
}
